#include <bits/stdc++.h>
using namespace std;

struct Point {
    long long u, v;
};

struct Extrema {
    long long minU, maxU, minV, maxV;
    bool empty;

    Extrema() : minU(0), maxU(0), minV(0), maxV(0), empty(true) {}

    void add(long long u, long long v) {
        if (empty) {
            minU = maxU = u;
            minV = maxV = v;
            empty = false;
        } else {
            minU = min(minU, u);
            maxU = max(maxU, u);
            minV = min(minV, v);
            maxV = max(maxV, v);
        }
    }

    void merge(const Extrema& other) {
        if (other.empty) return;
        if (empty) {
            *this = other;
        } else {
            minU = min(minU, other.minU);
            maxU = max(maxU, other.maxU);
            minV = min(minV, other.minV);
            maxV = max(maxV, other.maxV);
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<long long> x(n), y(n);
    for (auto& a : x) cin >> a;
    for (auto& a : y) cin >> a;

    vector<Point> points(n);
    long long minU = LLONG_MAX, maxU = LLONG_MIN;
    long long minV = LLONG_MAX, maxV = LLONG_MIN;
    int anchor = 0;

    for (int i = 0; i < n; ++i) {
        points[i] = {x[i] + y[i], x[i] - y[i]};
        if (points[i].u < minU) {
            minU = points[i].u;
            anchor = i;
        }
        maxU = max(maxU, points[i].u);
        minV = min(minV, points[i].v);
        maxV = max(maxV, points[i].v);
    }

    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b) {
        return points[a].v < points[b].v;
    });

    auto feasible = [&](long long d) -> bool {
        long long uLimit = minU + d;

        vector<Point> eligible;
        eligible.reserve(n);
        Extrema permanent;

        for (int id : order) {
            const auto& p = points[id];
            if (p.u <= uLimit)
                eligible.push_back(p);
            else
                permanent.add(p.u, p.v);
        }

        if (!permanent.empty &&
            (permanent.maxU - permanent.minU > d ||
             permanent.maxV - permanent.minV > d))
            return false;

        int m = static_cast<int>(eligible.size());
        vector<Extrema> prefix(m + 1), suffix(m + 1);

        for (int i = 0; i < m; ++i) {
            prefix[i + 1] = prefix[i];
            prefix[i + 1].add(eligible[i].u, eligible[i].v);
        }
        for (int i = m - 1; i >= 0; --i) {
            suffix[i] = suffix[i + 1];
            suffix[i].add(eligible[i].u, eligible[i].v);
        }

        long long lo = points[anchor].v - d;
        long long hi = points[anchor].v;
        int left = 0, right = 0;

        auto test = [&](long long b) -> bool {
            while (left < m && eligible[left].v < b) ++left;
            while (right < m && eligible[right].v <= b + d) ++right;

            Extrema remaining = permanent;
            remaining.merge(prefix[left]);
            remaining.merge(suffix[right]);

            return remaining.empty ||
                   (remaining.maxU - remaining.minU <= d &&
                    remaining.maxV - remaining.minV <= d);
        };

        if (test(lo)) return true;

        int i = 0, j = 0;
        while (i < m && eligible[i].v - d <= lo) ++i;
        while (j < m && eligible[j].v + 1 <= lo) ++j;

        while (i < m || j < m) {
            long long a = (i < m ? eligible[i].v - d : LLONG_MAX);
            long long b = (j < m ? eligible[j].v + 1 : LLONG_MAX);
            long long event = min(a, b);

            if (event > hi) break;

            while (i < m && eligible[i].v - d == event) ++i;
            while (j < m && eligible[j].v + 1 == event) ++j;

            if (test(event)) return true;
        }

        return false;
    };

    long long low = 0;
    long long high = max(maxU - minU, maxV - minV);

    while (low < high) {
        long long mid = low + (high - low) / 2;
        if (feasible(mid))
            high = mid;
        else
            low = mid + 1;
    }

    cout << low << '\n';
    return 0;
}
